def comps(cells):
    cells=set(cells)
    seen=set(); out=[]
    while cells:
        s=cells.pop(); stack=[s]; seen.add(s); comp=[]
        while stack:
            r,c=stack.pop(); comp.append((r,c))
            if (r+1,c) in cells and (r+1,c) not in seen: stack.append((r+1,c)); seen.add((r+1,c))
            if (r,c+1) in cells and (r,c+1) not in seen: stack.append((r,c+1)); seen.add((r,c+1))
            if (r-1,c) in cells and (r-1,c) not in seen: stack.append((r-1,c)); seen.add((r-1,c))
            if (r,c-1) in cells and (r,c-1) not in seen: stack.append((r,c-1)); seen.add((r,c-1))
        out.append(comp)
