G=load()
def shifts_best(I,O):
    rs,cs=np.where(I==1); S=I[rs.min():rs.max()+1, cs.min():cs.max()+1]
    best=None
    for k in [1,2,3]:
        R=np.rot90(S,k)
        for dr in range(-4,5):
            for dc in range(-4,5):
                # shift R: place R[r+dr, c+dc] onto O
                D=0
                for r in range(R.shape[0]):
                    for c in range(R.shape[1]):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<O.shape[0] and 0<=cc<O.shape[1]:
                            if R[r,c]!=O[rr,cc]: D+=1
                if best is None or D<best[0]: best=(D,k,dr,dc,R)
    return best
for p in ['1','2','3']:
    I=np.array(G[f'Demo pair {p} input']); O=np.array(G[f'Demo pair {p} output'])
    b=shifts_best(I,O)
    print(p,'best diff',b[0],'rot',b[1],'shift',b[2],b[3])

