G=load()
def match(I,O):
    I=np.array(I); O=np.array(O)
    nz=I.nonzero(); r0,c0,r1,c1=nz[0].min(),nz[1].min(),nz[0].max(),nz[1].max()
    s=I[r0:r1+1,c0:c1+1]; H,W=O.shape
    def sym(A):
        yield A; yield A[::-1,:]; yield A[:,::-1]
        # rotations
        R=A
        for _ in range(4):
            yield R; yield R[::-1,:]; yield R[:,::-1]
            R=np.rot90(R)
